// Validate required fields
const payload = $input.first().json;
const required = ['title', 'severity', 'message'];
const missing = required.filter(f => !payload[f]);
if (missing.length > 0) {
  throw new Error('Missing required fields: ' + missing.join(', '));
}
// Validate severity
const validSeverity = ['critical', 'warning', 'info'];
if (!validSeverity.includes(payload.severity)) {
  throw new Error('Invalid severity. Must be one of: ' + validSeverity.join(', '));
}
return [payload];

// Format message based on severity
const alert = $input.first().json;
const severityConfig = {
  critical: { emoji: ':red_circle:', color: '#E01E5A' },
  warning:  { emoji: ':warning:', color: '#FFC107' },
  info:     { emoji: ':information_source:', color: '#36A64F' }
};
const config = severityConfig[alert.severity] || severityConfig.info;

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: config.emoji + ' ' + alert.title }
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: alert.message }
  }
];

if (alert.fields) {
  const fieldItems = Object.entries(alert.fields).map(([name, value]) => ({
    type: 'mrkdwn',
    text: '*' + name + ':* ' + String(value)
  }));
  blocks.push({ type: 'section', fields: fieldItems });
}

if (alert.link) {
  blocks.push({
    type: 'actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: 'View Details' },
        url: alert.link,
        style: alert.severity === 'critical' ? 'danger' : 'primary'
      }
    ]
  });
}

return [{ blocks: blocks, text: alert.title }];
